package thaumcraft.verification;

import java.nio.file.*;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.inventory.*;
import net.minecraft.world.item.*;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.ClientTickEvent;
import thaumcraft.client.*;
import thaumcraft.items.*;
import thaumcraft.network.*;
import thaumcraft.registry.*;

/** Screens, models, audio events and real server requests; no desktop input. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ResearchUiLiveClient {
    private static int tick,waited;private static final List<String> checks=new ArrayList<>();private static final Set<String> sounds=new HashSet<>();private static CreativeModeInventoryScreen creative;private static ThaumonomiconScreen book;private static ResearchScreen table;
    private static java.lang.reflect.Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
    private static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks.add(label);}
    private static boolean await(boolean ready){if(ready){waited=0;return false;}if(++waited<200){tick--;return true;}throw new AssertionError("native server update timeout at tick "+tick);}
    private static int left(Object screen)throws Exception{return field(AbstractContainerScreen.class,"leftPos").getInt(screen);}
    private static int top(Object screen)throws Exception{return field(AbstractContainerScreen.class,"topPos").getInt(screen);}
    private static void point(Minecraft mc,double x,double y)throws Exception{var screen=mc.screen;var m=MouseHandler.class.getDeclaredMethod("onMove",long.class,double.class,double.class);m.setAccessible(true);double xx=x*mc.getWindow().getScreenWidth()/screen.width,yy=y*mc.getWindow().getScreenHeight()/screen.height;m.invoke(mc.mouseHandler,mc.getWindow().getWindow(),xx,yy);m.invoke(mc.mouseHandler,mc.getWindow().getWindow(),xx,yy);}
    private static void click(Minecraft mc,double x,double y,int button)throws Exception{point(mc,x,y);var screen=mc.screen;double scale=mc.getWindow().getGuiScaledWidth()/(double)screen.width;screen.mouseClicked(x*scale,y*scale,button);screen.mouseReleased(x*scale,y*scale,button);}
    private static void shot(Minecraft mc,String name)throws Exception{mc.getToasts().clear();try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/r3/evidence/"+name+".png"));}check(org.lwjgl.opengl.GL11.glGetError()==0,name+" renders without GL errors");}
    private static double[] nitor()throws Exception{var d=ClientKnowledge.definitions().get("NITOR");var x=ThaumonomiconScreen.class.getDeclaredMethod("nodeX",thaumcraft.api.research.ResearchDefinition.class);var y=ThaumonomiconScreen.class.getDeclaredMethod("nodeY",thaumcraft.api.research.ResearchDefinition.class);x.setAccessible(true);y.setAccessible(true);return new double[]{(int)x.invoke(book,d),(int)y.invoke(book,d)};}
    private static long sequence()throws Exception{return field(ResearchScreen.class,"sequence").getLong(table);}
    private static thaumcraft.menu.ResearchMenu menu(){return table.getMenu();}
    private static thaumcraft.api.research.ResearchNote note(){return ResearchNotes.read(menu().table.getItem(1));}
    private static void place(String aspect,int q,int r)throws Exception{long next=sequence()+1;field(ResearchScreen.class,"sequence").setLong(table,next);net.neoforged.neoforge.network.PacketDistributor.sendToServer(new ResearchActionPayload(menu().containerId,menu().token(),next,2,aspect,"",q,r));}
    @SubscribeEvent public static void sound(net.neoforged.neoforge.client.event.sound.PlaySoundEvent event){if("research-ui-live".equals(System.getProperty("thaumcraft.r3.phase"))&&event.getSound()!=null)sounds.add(event.getSound().getLocation().toString());}
    @SubscribeEvent public static void update(ClientTickEvent.Post event)throws Exception{
        if(!"research-ui-live".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=Minecraft.getInstance();if(mc.player==null||mc.level==null||mc.getOverlay()!=null||!mc.gameMode.hasInfiniteItems())return;if(tick==0&&(mc.screen!=null||!mc.player.getMainHandItem().is(R2Content.BOOK.get())||ClientKnowledge.snapshot().pool(thaumcraft.api.aspects.Aspects.AIR)!=100))return;
        try{
            ++tick;
            if(tick==20){mc.getToasts().clear();var tab=net.minecraft.core.registries.BuiltInRegistries.CREATIVE_MODE_TAB.get(net.minecraft.resources.ResourceLocation.parse("thaumcraft:thaumcraft"));field(CreativeModeInventoryScreen.class,"selectedTab").set(null,tab);creative=new CreativeModeInventoryScreen(mc.player,mc.level.enabledFeatures(),true);mc.setScreen(creative);point(mc,left(creative)+16,top(creative)+25);}
            if(tick==25){check(creative.getSlotUnderMouse()==null,"section banner has no hovered or selectable native slot");shot(mc,"research-creative-sections");click(mc,left(creative)+16,top(creative)+25,0);click(mc,left(creative)+16,top(creative)+25,1);click(mc,left(creative)+16,top(creative)+25,2);check(creative.getMenu().getCarried().isEmpty(),"all mouse buttons on banner keep creative cursor empty");var stack=new ItemStack(Items.IRON_INGOT);creative.getMenu().setCarried(stack);click(mc,left(creative)+16,top(creative)+25,0);check(ItemStack.matches(stack,creative.getMenu().getCarried()),"banner click also preserves an already carried item");creative.getMenu().setCarried(ItemStack.EMPTY);mc.player.closeContainer();mc.setScreen(null);}
            if(tick==35){ResearchHighlights.aspect();check(ResearchHighlights.unread("ASPECTS")&&ResearchHighlights.unread("BASICS"),"aspect discovery marks its book page and category as unread");mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);}
            if(tick==45){if(await(mc.screen instanceof ThaumonomiconScreen))return;book=(ThaumonomiconScreen)mc.screen;field(ThaumonomiconScreen.class,"category").set(book,"ALCHEMY");var centre=ThaumonomiconScreen.class.getDeclaredMethod("centreCategory");centre.setAccessible(true);centre.invoke(book);var pos=nitor();click(mc,pos[0],pos[1],0);check(field(ThaumonomiconScreen.class,"sequence").getLong(book)==0&&field(ThaumonomiconScreen.class,"popupUntil").getLong(book)==0,"creative research without materials sends no request or success popup");mc.player.connection.sendCommand("r3research supplies");}
            if(tick==55){if(await(mc.player.getInventory().getItem(1).is(Items.PAPER)&&mc.player.getInventory().getItem(2).is(R2Content.SCRIBING_TOOLS.get())))return;var pos=nitor();click(mc,pos[0],pos[1],0);check(field(ThaumonomiconScreen.class,"popupUntil").getLong(book)==0,"success popup waits for a server acknowledgement");}
            if(tick==65){if(await(field(ThaumonomiconScreen.class,"popupUntil").getLong(book)>0))return;check(sounds.contains("thaumcraft:write"),"acknowledged research note creation plays the original write sound");check(mc.player.getInventory().items.stream().anyMatch(s->{var n=ResearchNotes.read(s);return n!=null&&n.key.equals("NITOR");}),"book acknowledgement follows actual delivered note");}
            if(tick==70){point(mc,book.width-4,book.height-4);}
            if(tick==73){shot(mc,"research-book-issued-note");var pos=nitor();click(mc,pos[0],pos[1],0);check(field(ThaumonomiconScreen.class,"sequence").getLong(book)==1,"clicking a research already held as a note sends no duplicate request");point(mc,pos[0],pos[1]);}
            if(tick==78){shot(mc,"research-book-existing-note-tooltip");mc.player.closeContainer();mc.setScreen(null);mc.player.connection.sendCommand("r3research table");}
            if(tick==90){if(await(mc.screen instanceof ResearchScreen))return;table=(ResearchScreen)mc.screen;check(note()!=null&&!note().complete,"research table receives a native editable note");point(mc,left(table)+215,top(table)+120);}
            if(tick==140)mc.getToasts().clear(); if(tick==145){check(!((List<?>)field(ResearchScreen.class,"runes").get(table)).isEmpty(),"outside-grid parchment runes appear over time");shot(mc,"research-table-incomplete");place("lux",-1,0);}
            if(tick==155){if(await(note().grid.get(new thaumcraft.api.research.ResearchNote.Hex(-1,0)).aspect().equals("lux")))return;place("aer",0,0);}
            if(tick==165){if(await(note().grid.get(new thaumcraft.api.research.ResearchNote.Hex(0,0)).aspect().equals("aer")))return;place("lux",1,0);}
            if(tick==175){if(await(note().complete))return;check(sounds.contains("thaumcraft:learn"),"completion transition plays research sound");var stack=menu().table.getItem(1);check(stack.getHoverName().getString().equals(net.minecraft.network.chat.Component.translatable("item.discovery.name").getString()),"client slot changes its display name to Discovery");var model=mc.getItemRenderer().getModel(stack,mc.level,mc.player,0);var unfinished=stack.copy();var copy=note().copy();copy.complete=false;ResearchNotes.write(unfinished,copy);var before=mc.getItemRenderer().getModel(unfinished,mc.level,mc.player,0);check(!model.getParticleIcon().contents().name().equals(before.getParticleIcon().contents().name()),"native inventory model switches to rolled discovery texture");point(mc,left(table)+78,top(table)+18);}
            if(tick==180){shot(mc,"research-table-complete-discovery");long seq=sequence();click(mc,left(table)+169,top(table)+83,1);check(sequence()==seq,"RMB on a completed parchment never sends erase");var tips=net.minecraft.client.gui.screens.Screen.getTooltipFromItem(mc,menu().table.getItem(1));check(tips.stream().anyMatch(t->t.getString().contains("Nitor")),"completed item tooltip names Nitor");int luxBefore=ClientKnowledge.snapshot().pool(thaumcraft.api.aspects.Aspects.LIGHT);ResearchUiLiveClient.luxBefore=luxBefore;long next=sequence()+1;field(ResearchScreen.class,"sequence").setLong(table,next);net.neoforged.neoforge.network.PacketDistributor.sendToServer(new ResearchActionPayload(menu().containerId,menu().token(),next,3,"lux","",0,0));}
            if(tick==190){if(await(ClientKnowledge.snapshot().pool(thaumcraft.api.aspects.Aspects.LIGHT)>luxBefore))return;check(true,"quick aspect synthesis succeeds through the native server menu channel");var palette=ResearchScreen.class.getDeclaredMethod("palette");palette.setAccessible(true);var list=(List<thaumcraft.api.aspects.Aspect>)palette.invoke(table);int i=list.indexOf(thaumcraft.api.aspects.Aspects.LIGHT);field(ResearchScreen.class,"page").setInt(table,i/5);int local=i-i/5*5;point(mc,left(table)+10+local/5*16+8,top(table)+40+local%5*16+8);}
            if(tick==195){shot(mc,"research-table-components-tooltip");mc.player.closeContainer();mc.setScreen(null);for(int i=0;i<14;i++)ResearchNotifications.text("Queued research point "+(i+1),thaumcraft.api.aspects.Aspects.AIR);}
            if(tick==200){shot(mc,"research-notification-queue");var queue=(ResearchNotificationQueue<?>)field(ResearchNotifications.class,"TEXT").get(null);notificationCount=queue.remaining();check(notificationCount>0,"native notification renderer retains the excess count");}
            if(tick==205){mc.getToasts().clear();int aer=0;var palette=ResearchScreen.class.getDeclaredMethod("palette");palette.setAccessible(true);mc.player.connection.sendCommand("r3research table");}
            if(tick==215){if(await(mc.screen instanceof ResearchScreen))return;table=(ResearchScreen)mc.screen;var palette=ResearchScreen.class.getDeclaredMethod("palette");palette.setAccessible(true);var list=(List<thaumcraft.api.aspects.Aspect>)palette.invoke(table);int i=list.indexOf(thaumcraft.api.aspects.Aspects.AIR);field(ResearchScreen.class,"page").setInt(table,i/5);int local=i-i/5*5;double x=left(table)+10+local/5*16+8,y=top(table)+40+local%5*16+8;double scale=mc.getWindow().getGuiScaledWidth()/(double)table.width;table.mouseClicked(x*scale,y*scale,0);point(mc,left(table)+180,top(table)+130);check(field(ResearchScreen.class,"dragged").get(table)==thaumcraft.api.aspects.Aspects.AIR,"native palette click starts the aspect-coloured cursor light");}
            if(tick==220){shot(mc,"research-table-dragged-aer");double scale=mc.getWindow().getGuiScaledWidth()/(double)table.width;table.mouseReleased((left(table)+180)*scale,(top(table)+130)*scale,0);mc.player.closeContainer();mc.setScreen(null);}
            if(tick==400){var queue=(ResearchNotificationQueue<?>)field(ResearchNotifications.class,"TEXT").get(null);check(queue.remaining()<notificationCount,"native notification list feeds overflow after the oldest row leaves");shot(mc,"research-notification-after-scroll");check(sounds.contains("thaumcraft:write")&&sounds.contains("thaumcraft:learn"),"research sound events reach the native sound engine");finish(mc,true,null);}
        }catch(Throwable error){error.printStackTrace();finish(mc,false,error.toString());}
    }
    private static int luxBefore;
    private static int notificationCount;
    private static void finish(Minecraft mc,boolean pass,String error)throws Exception{var result=new LinkedHashMap<String,Object>();result.put("passed",pass);result.put("count",checks.size());result.put("checks",checks);result.put("sounds",sounds);if(error!=null)result.put("error",error);Files.writeString(Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/r3/evidence/research-ui-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result));mc.stop();}
}
